import React, { useEffect, useState } from 'react';
import { coursesAPI, testingAPI } from '../../api';
import { useAuth } from '../../context/AuthContext';

export default function StudentDashboard() {
  const { user } = useAuth();
  const [enrollments, setEnrollments] = useState([]);

  useEffect(() => {
    coursesAPI.myCourses().then(({ data }) => setEnrollments(Array.isArray(data) ? data : data.results || []));
  }, []);

  return (
    <div>
      <h1 style={s.h1}>Привет, {user?.first_name}! 🎓</h1>
      <p style={s.sub}>Ваш учебный кабинет</p>

      <div style={s.grid}>
        <div style={s.card}>
          <div style={s.cardIcon}>📚</div>
          <div style={s.cardVal}>{enrollments.length}</div>
          <div style={s.cardLabel}>Курсов записано</div>
        </div>
        <div style={s.card}>
          <div style={s.cardIcon}>✅</div>
          <div style={s.cardVal}>
            {enrollments.filter(e => e.progress === 100).length}
          </div>
          <div style={s.cardLabel}>Завершено</div>
        </div>
      </div>

      <div style={s.section}>
        <h2 style={s.h2}>Мои курсы</h2>
        {enrollments.length === 0 ? (
          <div style={s.empty}>Вы ещё не записаны ни на один курс</div>
        ) : (
          enrollments.map(e => (
            <div key={e.id} style={s.courseCard}>
              <div>
                <div style={s.courseTitle}>{e.course_title}</div>
                <div style={s.progressLabel}>Прогресс: {e.progress}%</div>
              </div>
              <div style={s.progressBar}>
                <div style={{ ...s.progressFill, width: `${e.progress}%` }} />
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

const s = {
  h1: { fontSize: 28, fontWeight: 700, color: '#1e293b', margin: '0 0 4px' },
  sub: { color: '#64748b', marginBottom: 28 },
  grid: { display: 'flex', gap: 16, marginBottom: 28 },
  card: {
    width: 160, background: '#fff', borderRadius: 12, padding: 20,
    boxShadow: '0 1px 4px rgba(0,0,0,0.08)', textAlign: 'center',
    borderTop: '4px solid #6366f1'
  },
  cardIcon: { fontSize: 28, marginBottom: 8 },
  cardVal: { fontSize: 28, fontWeight: 700, color: '#1e293b' },
  cardLabel: { fontSize: 13, color: '#64748b', marginTop: 4 },
  section: {},
  h2: { fontSize: 20, fontWeight: 600, color: '#1e293b', marginBottom: 16 },
  empty: {
    background: '#fff', borderRadius: 12, padding: 32,
    textAlign: 'center', color: '#94a3b8'
  },
  courseCard: {
    background: '#fff', borderRadius: 12, padding: 20, marginBottom: 12,
    boxShadow: '0 1px 4px rgba(0,0,0,0.08)'
  },
  courseTitle: { fontSize: 16, fontWeight: 600, color: '#1e293b', marginBottom: 8 },
  progressLabel: { fontSize: 12, color: '#64748b', marginBottom: 8 },
  progressBar: { height: 8, background: '#f1f5f9', borderRadius: 4, overflow: 'hidden' },
  progressFill: { height: '100%', background: '#6366f1', borderRadius: 4, transition: 'width 0.3s' },
};
